from datetime import datefrom sqlalchemy import String, Date, ForeignKeyfrom sqlalchemy.orm import Mapped, mapped_columnfrom database import Baseclass UserProfile(Base):    __tablename__ = "user_profiles"    id: Mapped[int] = mapped_column(        primary_key=True,        autoincrement=True    )    user_id: Mapped[int] = mapped_column(        ForeignKey("users.id", ondelete="CASCADE"),        nullable=False,        unique=True    )    first_name: Mapped[str] = mapped_column(        String(100),        nullable=False    )    last_name: Mapped[str] = mapped_column(        String(100),        nullable=False    )    phone: Mapped[str | None] = mapped_column(        String(20),        nullable=True    )    birth_date: Mapped[date | None] = mapped_column(        Date,        nullable=True    )